sys_script_include.script:
var CampusFoodSPEntryPage = Class.create();

CampusFoodSPEntryPage.prototype = {

    initialize: function() {
        this.portal = "/food_services/";
    },

    getFirstPageURL: function() {

        if (gs.getUser().hasRole('x_snc_campus_foo_1.admin')) {
            return this.portal + "?id=food_service_admin_dashboard_page";
        }

        if (gs.getUser().hasRole('x_snc_campus_foo_1.manager')) {
            return this.portal + "?id=food_service_manager_dashboard_page";
        }

        if (gs.getUser().hasRole('x_snc_campus_foo_1.staff')) {
            return this.portal + "?id=food_services_staff_dashboard_page";
        }

        if (gs.getUser().hasRole('x_snc_campus_foo_1.student')) {
            return this.portal + "?id=food_service_student_dashbaord";
        }

        return this.portal;
    },

    type: 'CampusFoodSPEntryPage'
};
